//! Tray icons built from assets/ (generated by assets/make_icons.py).
//!
//! macOS: the black glyph as a *template* image, so the menu bar tints it for
//!        light / dark mode. State is shown by opacity and a badge.
//! Windows: the white tile with a coloured status dot (the taskbar is not
//!        tinted, so colour works and the tile stays visible on dark themes).

use tray_icon::Icon;

use crate::State;

#[cfg(target_os = "macos")]
const BASE: &[u8] = include_bytes!("../assets/glyph.png");
#[cfg(not(target_os = "macos"))]
const BASE: &[u8] = include_bytes!("../assets/tile.png");

pub const IS_TEMPLATE: bool = cfg!(target_os = "macos");

struct Rgba {
    w: u32,
    h: u32,
    px: Vec<u8>,
}

fn decode(bytes: &[u8]) -> Rgba {
    let mut dec = png::Decoder::new(bytes);
    dec.set_transformations(png::Transformations::normalize_to_color8() | png::Transformations::ALPHA);
    let mut reader = dec.read_info().expect("icon png");
    let mut px = vec![0; reader.output_buffer_size()];
    let info = reader.next_frame(&mut px).expect("icon png");
    px.truncate(info.buffer_size());
    // expand gray+alpha to RGBA if needed
    let px = match info.color_type {
        png::ColorType::Rgba => px,
        png::ColorType::GrayscaleAlpha => px.chunks(2).flat_map(|c| [c[0], c[0], c[0], c[1]]).collect(),
        png::ColorType::Rgb => px.chunks(3).flat_map(|c| [c[0], c[1], c[2], 255]).collect(),
        _ => px.iter().flat_map(|&g| [g, g, g, 255]).collect(),
    };
    Rgba { w: info.width, h: info.height, px }
}

/// Draws an anti-aliased disc (or ring when `hole` > 0) of radius `r` centred
/// at (cx, cy), blending `rgb` over the image.
fn disc(img: &mut Rgba, cx: f32, cy: f32, r: f32, hole: f32, rgb: [u8; 3], border: Option<f32>) {
    for y in 0..img.h {
        for x in 0..img.w {
            let d = ((x as f32 + 0.5 - cx).powi(2) + (y as f32 + 0.5 - cy).powi(2)).sqrt();
            // knock out a transparent border so the badge reads on the glyph
            if let Some(b) = border {
                let k = (r + b - d).clamp(0.0, 1.0);
                if k > 0.0 {
                    let i = ((y * img.w + x) * 4) as usize;
                    img.px[i + 3] = (img.px[i + 3] as f32 * (1.0 - k)) as u8;
                }
            }
            let mut a = (r - d).clamp(0.0, 1.0);
            if hole > 0.0 {
                a = a.min((d - hole).clamp(0.0, 1.0));
            }
            if a <= 0.0 {
                continue;
            }
            let i = ((y * img.w + x) * 4) as usize;
            for c in 0..3 {
                img.px[i + c] = (img.px[i + c] as f32 * (1.0 - a) + rgb[c] as f32 * a) as u8;
            }
            img.px[i + 3] = (img.px[i + 3] as f32).max(a * 255.0) as u8;
        }
    }
}

pub fn tray(state: State) -> Icon {
    let mut img = decode(BASE);
    let (w, h) = (img.w as f32, img.h as f32);

    if IS_TEMPLATE {
        // opacity: searching / disconnected look faded; badge when on air
        let alpha = match state {
            State::Searching => 0.45,
            State::Paused => 0.25,
            State::Connected | State::OnAir => 1.0,
        };
        for p in img.px.chunks_mut(4) {
            p[3] = (p[3] as f32 * alpha) as u8;
        }
        if state == State::OnAir {
            disc(&mut img, w * 0.80, h * 0.80, w * 0.16, 0.0, [0, 0, 0], Some(w * 0.06));
        }
    } else {
        let (rgb, ring) = match state {
            State::Searching => ([0x8a, 0x8a, 0x96], false),
            State::Paused => ([0x8a, 0x8a, 0x96], true),
            State::Connected => ([0x2e, 0xc2, 0x7e], false),
            State::OnAir => ([0xff, 0x4d, 0x6a], false),
        };
        let r = w * 0.20;
        let (cx, cy) = (w - r - 1.0, h - r - 1.0);
        disc(&mut img, cx, cy, r + w * 0.05, 0.0, [0xff, 0xff, 0xff], None); // white rim
        disc(&mut img, cx, cy, r, if ring { r * 0.5 } else { 0.0 }, rgb, None);
    }
    Icon::from_rgba(img.px, img.w, img.h).expect("icon")
}
